&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;We offer:&lt;/strong&gt;&lt;/span&gt;&lt;/div&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Nice work environment&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Competitive Salary&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Health Insurance&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;Stock Options&lt;/span&gt;&lt;/li&gt;
